const FOODTABS=[["plan","Wochenplan"],["kita","🎒 Kita-Essen ›"]];
// Essen hat zwei Seiten (Florian 16.11.2026): „Heute und Wochenplan“ (Chips Heute, Wochenplan, Kita-Essen) und „Rezepte“; Tipp auf den Reiter blättert weiter
function foodPager(p){return `<div class="pager" role="group" aria-label="Seiten von Essen"><div class="pdots">${["heute","rezepte"].map((k,i)=>[k,TAB_PAGES.essen[i]]).map((x,i)=>`<button class="pdot" data-food="${x[0]}" aria-pressed="${i===p}"><b>${x[1]}</b></button>`).join("")}</div></div>`}
function shopItems(){const m=(S.food&&S.food.shop)||{};return Object.keys(m).filter(k=>m[k]).map(k=>Object.assign({id:k},m[k])).sort((a,b)=>(a.at||0)-(b.at||0))}
function shopFavs(){const f=(S.food&&S.food.fav)||{};const open=new Set(shopItems().filter(i=>!i.done).map(i=>i.name.toLowerCase()));
  return Object.keys(f).filter(k=>f[k]&&f[k].n>0&&!open.has((f[k].name||"").toLowerCase())).sort((a,b)=>f[b].n-f[a].n).slice(0,14).map(k=>f[k].name)}
function favKey(name){let h=0;const s=name.toLowerCase();for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))>>>0;return "f"+h.toString(36)}
async function shopAdd(name,urg){name=(name||"").trim();if(/^[!❗]/.test(name)){urg=true;name=name.replace(/^[!❗]+\s*/,"")}name=qtyNorm(name).slice(0,80);if(!name)return;
  const dup=shopItems().find(i=>!i.done&&i.name.toLowerCase()===name.toLowerCase());if(dup){if(urg&&!dup.urg){await S.store.setPath("food/shop/"+dup.id+"/urg",true);toast("❗ Als heute nötig markiert");return}toast("Steht schon auf der Liste");return}
  const id="i"+Date.now().toString(36)+Math.random().toString(36).slice(2,5);
  try{await S.store.setPath("food/shop/"+id,Object.assign({name,done:false,at:Date.now(),by:S.me||""},urg?{urg:true}:{}));
    const qs=qtySplit(name),fk=favKey(qs.rest),old=(S.food.fav||{})[fk]||{};await S.store.setPath("food/fav/"+fk,Object.assign({},old,{name:qs.rest,n:(old.n||0)+1},qs.q?{q:qs.q}:{}))}
  catch(_){toast("Konnte nicht speichern. Bitte Verbindung prüfen.")}}
const DAYN=["Montag","Dienstag","Mittwoch","Donnerstag","Freitag","Samstag","Sonntag"];
function recs(){const m=(S.food&&S.food.rec)||{};return Object.keys(m).filter(k=>m[k]).map(k=>Object.assign({id:k},m[k])).sort((a,b)=>(a.name||"").localeCompare(b.name||"","de"))}
function recIng(r){return ((r&&r.ing)||"").split("\n").map(x=>x.trim()).filter(Boolean)}
const PANTRY_DEF=["Salz","Pfeffer","Öl","Olivenöl","Rapsöl","Sonnenblumenöl","Zucker","Mehl","Essig","Gemüsebrühe","Paprikapulver","Currypulver","Kreuzkümmel","Zimt","Muskat","Muskatnuss","Oregano","Chiliflocken","Lorbeerblatt","Lorbeerblätter","Backpulver","Natron","Speisestärke","Wasser","Gewürze"];
function pantry(){const v=S.food&&S.food.pantry;return typeof v==="string"?v.split("\n").map(x=>x.trim()).filter(Boolean):PANTRY_DEF}
function isPantry(line,list){const l=" "+String(line||"").toLowerCase()+" ";return (list||pantry()).some(t=>{t=t.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g,"\\$&");return new RegExp("(^|[^a-zäöüß])"+t+"($|[^a-zäöüß])").test(l)})}
const hasQty=l=>/\d|[½¼¾⅓]|\b(eine?n?|Prise|Msp|Bund|Zehen?|Stück|Stiele?|Zweige?|Dosen?|Packung|Handvoll|etwas)\b/i.test(l);
// Ältere Rezepte und Plantage haben Zutaten ohne Mengen. Gibt es das Gericht in der aktuellen Recherche mit Mengen, nimm diese Zeilen.
function withQty(name,lines){const miss=lines.filter(l=>!hasQty(l)).length;if(!miss||!name)return lines;const nm=name.trim().toLowerCase();
  const x=[...((S.wideas&&S.wideas.items)||[]),...((S.ideas&&S.ideas.items)||[]),...((S.ideas&&S.ideas.emmi)||[])].find(y=>y&&y.name&&y.name.trim().toLowerCase()===nm&&Array.isArray(y.ing));
  if(!x)return lines;const ing=x.ing.map(String);return ing.filter(l=>!hasQty(l)).length<miss?ing:lines}
async function shopAddMany(list,src,opt){opt=opt||{};src=(src||"").trim().slice(0,80);list=withQty(src,list);let n=0,skip=0,noq=0;const pl=pantry();
  // Gleiche Zeile vom selben Rezept (oder beide ohne Rezept) nicht doppelt; von einem anderen Rezept schon, die Liste rechnet sie zusammen.
  const have=new Set(shopItems().filter(i=>!i.done).map(i=>i.name.toLowerCase()+"|"+(i.src||"")));
  for(const raw of list){const name=raw.trim().slice(0,80),hk=name.toLowerCase()+"|"+src;if(!name||have.has(hk))continue;if(!opt.force&&isPantry(name,pl)){skip++;continue}have.add(hk);if(!hasQty(name))noq++;
    const id="i"+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
    try{const v={name,done:false,at:Date.now()+n,by:S.me||""};if(src)v.src=src;await S.store.setPath("food/shop/"+id,v);n++}catch(_){toast("Konnte nicht speichern. Bitte Verbindung prüfen.");return {n,skip,noq,err:1}}}
  if(!opt.quiet)shopToast(n,skip,noq);return {n,skip,noq}}
function shopToast(n,skip,noq){toast((n?n+(n===1?" Zutat":" Zutaten")+" auf der Einkaufsliste":"Steht alles schon auf der Liste")+(skip?". "+skip+" aus dem Vorrat weggelassen":"")+(noq?". "+noq+" ohne Menge (älteres Rezept)":""))}
